+img{max-width:100%;display:block}
+a{color:inherit;text-decoration:none}
+
+.container{max-width:var(--max);margin:0 auto;padding:0 20px}
+.section{padding:44px 0}
+.section.tight{padding:28px 0}
+
+.chip{
+  display:inline-flex;align-items:center;gap:8px;
+  padding:8px 10px;border:1px solid var(--line);
+  background:rgba(255,255,255,.75);
+  border-radius:999px;color:var(--muted);font-size:13px
+}
+
+.sr-only{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
+
+.skip-link{
+  position:absolute;left:-9999px;top:10px;
+  background:var(--surface);border:1px solid var(--line);
+  padding:10px 12px;border-radius:12px;z-index:999
+}
+.skip-link:focus{left:12px}
+
+/* Header */
+.topbar{
+  position:sticky;top:0;z-index:50;
+  background:rgba(255,255,255,.86);
+  backdrop-filter:saturate(180%) blur(14px);
+  border-bottom:1px solid rgba(230,235,243,.85)
+}
+.topbar-inner{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 0}
+
+.brand{
+  display:flex;align-items:center;gap:10px;font-weight:800;letter-spacing:-.02em
+}
+.brand-mark{
+  width:34px;height:34px;border-radius:12px;
+  background:linear-gradient(135deg, var(--brand) 0%, var(--brand-2) 65%);
+  box-shadow:inset 0 0 0 1px rgba(255,255,255,.22)
+}
+.brand-name{font-size:16px}
+.brand-sub{display:block;font-weight:600;color:var(--muted);font-size:12px;margin-top:2px}
+
+.nav{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
+.nav a{
+  padding:9px 12px;border-radius:999px;
+  color:var(--muted);font-weight:600;font-size:14px
+}
+.nav a:hover{background:rgba(0,59,149,.06);color:var(--brand)}
+.nav a[aria-current="page"]{background:rgba(0,59,149,.10);color:var(--brand)}
+
+.header-actions{display:flex;align-items:center;gap:10px}
+
+.btn{
+  appearance:none;border:0;cursor:pointer;
+  display:inline-flex;align-items:center;justify-content:center;gap:10px;
+  padding:10px 14px;border-radius:12px;
+  font-weight:700;font-size:14px
+}
+.btn.primary{background:var(--cta);color:var(--cta-ink)}
+.btn.primary:hover{filter:brightness(.97)}
+.btn.secondary{background:rgba(0,59,149,.08);color:var(--brand)}
+.btn.secondary:hover{background:rgba(0,59,149,.12)}
+.btn.ghost{background:transparent;border:1px solid var(--line);color:var(--muted)}
+.btn.ghost:hover{background:rgba(11,18,32,.03);color:var(--text)}
+
+/* Hero */
+.hero{
+  padding:34px 0 26px;
+  background:
+    radial-gradient(900px 380px at 20% 5%, rgba(0,108,228,.22) 0%, rgba(0,108,228,0) 60%),
+    radial-gradient(900px 380px at 80% 10%, rgba(255,183,0,.25) 0%, rgba(255,183,0,0) 55%)
+}
+.hero-grid{display:grid;grid-template-columns: 1.08fr .92fr;gap:20px;align-items:stretch}
+.hero-copy{
+  background:rgba(255,255,255,.75);
+  border:1px solid rgba(230,235,243,.95);
+  border-radius:var(--radius);
+  padding:24px;
+  box-shadow:var(--shadow-sm)
+}
+.hero h1{margin:0;font-size:40px;letter-spacing:-.03em;line-height:1.06}
+.hero p{margin:10px 0 0;color:var(--muted);font-size:16px;line-height:1.5}
+
+.hero-aside{
+  border-radius:var(--radius);
+  border:1px solid rgba(230,235,243,.95);
+  background:linear-gradient(180deg, rgba(0,59,149,.05) 0%, rgba(0,108,228,.06) 60%, rgba(255,183,0,.07) 100%);
+  padding:18px;
+  box-shadow:var(--shadow-sm)
+}
+.hero-aside .note-title{font-weight:800;letter-spacing:-.02em}
+.hero-aside .note{margin-top:8px;color:var(--muted);font-size:14px;line-height:1.5}
+.hero-aside .stats{display:grid;grid-template-columns:1fr;gap:10px;margin-top:14px}
+.hero-aside .stat{
+  display:flex;gap:12px;align-items:flex-start;
+  padding:12px;border-radius:14px;background:rgba(255,255,255,.72);
+  border:1px solid rgba(230,235,243,.9)
+}
+.icon{
+  width:34px;height:34px;border-radius:12px;
+  display:grid;place-items:center;
+  background:rgba(0,59,149,.10);color:var(--brand)
+}
+.stat strong{display:block;font-size:14px}
+.stat span{display:block;color:var(--muted);font-size:13px;margin-top:2px}
+
+/* Search */
+.search-card{
+  margin-top:16px;
+  border-radius:var(--radius);
+  border:1px solid rgba(230,235,243,.95);
+  background:rgba(255,255,255,.90);
+  box-shadow:var(--shadow);
+  overflow:hidden
+}
+.tabs{
+  display:flex;gap:6px;flex-wrap:wrap;
+  padding:10px;border-bottom:1px solid rgba(230,235,243,.9);
+  background:rgba(0,59,149,.04)
+}
+.tab{
+  border:1px solid transparent;
+  background:transparent;
+  padding:10px 12px;border-radius:999px;
+  font-weight:800;font-size:13px;color:var(--muted);
+  cursor:pointer
+}
+.tab[aria-selected="true"]{
+  background:rgba(0,59,149,.12);
+  color:var(--brand);
+  border-color:rgba(0,59,149,.10)
+}
+.tab:focus{outline:2px solid rgba(0,108,228,.35);outline-offset:2px}
+
+.search-form{padding:14px}
+.form-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr auto;gap:10px;align-items:end}
+.field label{display:block;font-size:12px;font-weight:800;color:var(--muted);margin:0 0 6px}
+.field input,.field select{
+  width:100%;padding:12px 12px;
+  border:1px solid var(--line);border-radius:12px;
+  font-size:14px;background:var(--surface)
+}
+.field input:focus,.field select:focus{outline:2px solid rgba(0,108,228,.35);outline-offset:2px;border-color:rgba(0,108,228,.30)}
+.form-actions{display:flex;justify-content:flex-end}
+.form-actions .btn{padding:12px 18px;border-radius:14px}
+
+.form-meta{display:flex;gap:14px;flex-wrap:wrap;margin-top:10px;align-items:center}
+.checkbox{display:flex;align-items:center;gap:10px;color:var(--muted);font-weight:700;font-size:13px}
+.checkbox input{width:18px;height:18px}
+
+/* Section headings */
+.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;margin-bottom:16px}
+.section-head h2{margin:0;font-size:24px;letter-spacing:-.02em}
+.section-head p{margin:6px 0 0;color:var(--muted);max-width:64ch}
+.section-head .right{display:flex;gap:10px;align-items:center}
+
+/* Cards & grids */
+.grid{display:grid;gap:14px}
+.grid.cols-3{grid-template-columns:repeat(3,minmax(0,1fr))}
+.grid.cols-4{grid-template-columns:repeat(4,minmax(0,1fr))}
+.grid.cols-5{grid-template-columns:repeat(5,minmax(0,1fr))}
+
+.card{
+  background:var(--surface);
+  border:1px solid var(--line);
+  border-radius:var(--radius);
+  overflow:hidden;
+  box-shadow:var(--shadow-sm)
+}
+.card.pad{padding:16px}
+.card:hover{transform:translateY(-1px);transition:transform .12s ease}
+
+.media{
+  background:linear-gradient(135deg, rgba(0,108,228,.22) 0%, rgba(0,59,149,.12) 35%, rgba(255,183,0,.20) 100%);
+  height:140px
+}
+.media.tall{height:180px}
+
+.card-body{padding:14px}
+.kicker{color:var(--muted);font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.06em}
+.title{font-weight:900;letter-spacing:-.01em;margin:6px 0 0}
+.sub{margin:6px 0 0;color:var(--muted);font-size:13px;line-height:1.45}
+
+.meta-row{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:12px}
+.price{font-weight:900;font-size:18px;letter-spacing:-.02em}
+.price .was{color:var(--muted);text-decoration:line-through;font-weight:800;font-size:13px;margin-right:6px}
+.badge{
+  display:inline-flex;align-items:center;gap:8px;
+  padding:8px 10px;border-radius:999px;
+  background:rgba(0,108,228,.10);color:var(--brand-2);
+  font-weight:900;font-size:12px
+}
+.badge.gold{background:rgba(255,183,0,.18);color:#6b4d00}
+.rating{
+  display:inline-flex;align-items:center;gap:8px;
+  font-size:13px;color:var(--muted);font-weight:700
+}
+.rating b{
+  display:inline-grid;place-items:center;
+  width:26px;height:26px;border-radius:10px;
+  background:rgba(15,118,110,.12);color:var(--success);font-weight:900
+}
+
+/* Pills tabs (content sections) */
+.pill-tabs{display:flex;flex-wrap:wrap;gap:8px}
+.pill-tabs button{
+  border:1px solid var(--line);
+  background:rgba(255,255,255,.8);
+  padding:9px 12px;border-radius:999px;
+  cursor:pointer;
+  font-weight:900;font-size:13px;color:var(--muted)
+}
+.pill-tabs button[aria-selected="true"]{
+  border-color:rgba(0,59,149,.22);
+  background:rgba(0,59,149,.08);
+  color:var(--brand)
+}
+.pill-tabs button:focus{outline:2px solid rgba(0,108,228,.35);outline-offset:2px}
+
+/* Carousel */
+.carousel{
+  position:relative
+}
+.carousel-viewport{
+  display:flex;gap:14px;
+  overflow:auto;
+  scroll-behavior:smooth;
+  padding-bottom:8px
+}
+.carousel-viewport::-webkit-scrollbar{height:10px}
+.carousel-viewport::-webkit-scrollbar-thumb{background:rgba(91,102,122,.25);border-radius:999px}
+.carousel-viewport::-webkit-scrollbar-track{background:rgba(230,235,243,.7);border-radius:999px}
+
+.carousel .card{min-width:280px;max-width:280px;flex:0 0 auto}
+
+.caro-btn{
+  position:absolute;top:50%;transform:translateY(-50%);
+  width:42px;height:42px;border-radius:14px;
+  border:1px solid var(--line);
+  background:rgba(255,255,255,.92);
+  box-shadow:var(--shadow-sm);
+  cursor:pointer
+}
+.caro-btn:hover{background:#fff}
+.caro-btn:focus{outline:2px solid rgba(0,108,228,.35);outline-offset:2px}
+.caro-btn.prev{left:-10px}
+.caro-btn.next{right:-10px}
+
+/* FAQ */
+.accordion{display:grid;gap:10px}
+.acc-item{border:1px solid var(--line);border-radius:16px;background:rgba(255,255,255,.92);overflow:hidden}
+.acc-btn{
+  width:100%;text-align:left;
+  padding:14px 14px;
+  display:flex;align-items:center;justify-content:space-between;gap:10px;
+  background:transparent;border:0;cursor:pointer
+}
+.acc-btn strong{font-size:14px;letter-spacing:-.01em}
+.acc-btn span{color:var(--muted);font-weight:900}
+.acc-panel{padding:0 14px 14px;color:var(--muted);line-height:1.6;display:none}
+.acc-item[data-open="true"] .acc-panel{display:block}
+.acc-item[data-open="true"] .acc-btn span{transform:rotate(45deg)}
+
+/* Footer */
+footer{background:#071534;color:#e9eef8}
+.footer-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;padding:34px 0}
+.footer-col h3{margin:0 0 10px;font-size:13px;letter-spacing:.06em;text-transform:uppercase;color:#b9c6df}
+.footer-col a{display:block;color:#e9eef8;opacity:.88;padding:6px 0;font-size:13px}
+.footer-col a:hover{opacity:1;text-decoration:underline}
+.footer-bottom{border-top:1px solid rgba(233,238,248,.14);padding:16px 0;color:#b9c6df;font-size:13px}
+
+/* Utilities */
+.callout{
+  border-radius:var(--radius);
+  border:1px solid rgba(230,235,243,.95);
+  background:linear-gradient(180deg, rgba(255,183,0,.14) 0%, rgba(0,108,228,.06) 90%);
+  box-shadow:var(--shadow-sm);
+  padding:16px
+}
+.split{display:grid;grid-template-columns:1fr 1fr;gap:14px}
+.muted{color:var(--muted)}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns:1fr}
+  .form-grid{grid-template-columns:1fr 1fr;}
+  .form-actions{grid-column:1 / -1}
+  .grid.cols-5{grid-template-columns:repeat(3,minmax(0,1fr))}
+  .grid.cols-4{grid-template-columns:repeat(2,minmax(0,1fr))}
+  .grid.cols-3{grid-template-columns:repeat(2,minmax(0,1fr))}
+  .footer-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
+  .caro-btn.prev{left:6px}
+  .caro-btn.next{right:6px}
+}
+
+@media (max-width: 560px){
+  .hero h1{font-size:32px}
+  .form-grid{grid-template-columns:1fr}
+  .grid.cols-4,.grid.cols-3,.grid.cols-5{grid-template-columns:1fr}
+  .footer-grid{grid-template-columns:1fr}
+  .nav{display:none}
+}
+
*** End Patch
PATCH

