+.media.tall{height:180px}
+
+.card-body{padding:14px}
+.kicker{color:var(--muted);font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.06em}
+.title{font-weight:900;letter-spacing:-.01em;margin:6px 0 0}
+.sub{margin:6px 0 0;color:var(--muted);font-size:13px;line-height:1.45}
+
+.meta-row{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:12px}
+.price{font-weight:900;font-size:18px;letter-spacing:-.02em}
+.price .was{color:var(--muted);text-decoration:line-through;font-weight:800;font-size:13px;margin-right:6px}
+.badge{
+  display:inline-flex;align-items:center;gap:8px;
+  padding:8px 10px;border-radius:999px;
+  background:rgba(0,108,228,.10);color:var(--brand-2);
+  font-weight:900;font-size:12px
+}
+.badge.gold{background:rgba(255,183,0,.18);color:#6b4d00}
+.rating{
+  display:inline-flex;align-items:center;gap:8px;
+  font-size:13px;color:var(--muted);font-weight:700
+}
+.rating b{
+  display:inline-grid;place-items:center;
+  width:26px;height:26px;border-radius:10px;
+  background:rgba(15,118,110,.12);color:var(--success);font-weight:900
+}
+
+/* Pills tabs (content sections) */
+.pill-tabs{display:flex;flex-wrap:wrap;gap:8px}
+.pill-tabs button{
+  border:1px solid var(--line);
+  background:rgba(255,255,255,.8);
