+  cursor:pointer;
+  font-weight:900;font-size:13px;color:var(--muted)
+}
+.pill-tabs button[aria-selected="true"]{
+  border-color:rgba(0,59,149,.22);
+  background:rgba(0,59,149,.08);
+  color:var(--brand)
+}
+.pill-tabs button:focus{outline:2px solid rgba(0,108,228,.35);outline-offset:2px}
+
+/* Carousel */
+.carousel{
+  position:relative
+}
+.carousel-viewport{
+  display:flex;gap:14px;
+  overflow:auto;
+  scroll-behavior:smooth;
+  padding-bottom:8px
+}
+.carousel-viewport::-webkit-scrollbar{height:10px}
+.carousel-viewport::-webkit-scrollbar-thumb{background:rgba(91,102,122,.25);border-radius:999px}
+.carousel-viewport::-webkit-scrollbar-track{background:rgba(230,235,243,.7);border-radius:999px}
+
+.carousel .card{min-width:280px;max-width:280px;flex:0 0 auto}
+
+.caro-btn{
+  position:absolute;top:50%;transform:translateY(-50%);
+  width:42px;height:42px;border-radius:14px;
+  border:1px solid var(--line);
+  background:rgba(255,255,255,.92);
+  box-shadow:var(--shadow-sm);
+  cursor:pointer
+}
+.caro-btn:hover{background:#fff}
+.caro-btn:focus{outline:2px solid rgba(0,108,228,.35);outline-offset:2px}
+.caro-btn.prev{left:-10px}
+.caro-btn.next{right:-10px}
+
+/* FAQ */
+.accordion{display:grid;gap:10px}
+.acc-item{border:1px solid var(--line);border-radius:16px;background:rgba(255,255,255,.92);overflow:hidden}
+.acc-btn{
+  width:100%;text-align:left;
+  padding:14px 14px;
+  display:flex;align-items:center;justify-content:space-between;gap:10px;
+  background:transparent;border:0;cursor:pointer
+}
+.acc-btn strong{font-size:14px;letter-spacing:-.01em}
+.acc-btn span{color:var(--muted);font-weight:900}
+.acc-panel{padding:0 14px 14px;color:var(--muted);line-height:1.6;display:none}
+.acc-item[data-open="true"] .acc-panel{display:block}
+.acc-item[data-open="true"] .acc-btn span{transform:rotate(45deg)}
+
+/* Footer */
+footer{background:#071534;color:#e9eef8}
+.footer-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;padding:34px 0}
+.footer-col h3{margin:0 0 10px;font-size:13px;letter-spacing:.06em;text-transform:uppercase;color:#b9c6df}
+.footer-col a{display:block;color:#e9eef8;opacity:.88;padding:6px 0;font-size:13px}
+.footer-col a:hover{opacity:1;text-decoration:underline}
+.footer-bottom{border-top:1px solid rgba(233,238,248,.14);padding:16px 0;color:#b9c6df;font-size:13px}
